B=[['拉丁 intra','在里面、在某个范围之内']]
W=[
E('intranet','/ˈɪntrənet/','内联网；机构内部网络','公司的公告、请假入口、内部资料，都放在供员工使用的同一张网里。','现代英语 intra- 内部 + net 网络，按 internet 一类网络名称构词。',B+[['intra- + net','内部使用的网络'],['英语 intranet','组织内部的信息与协作网络']],'核心是服务对象限于某个组织。它可以包含内部网页、搜索和业务系统，也可以允许员工经过验证后远程访问；“内部”指访问范围，不要求每个人都坐在同一间办公室。','the company intranet；post on the intranet；access the intranet。','internet 是公共互联网；intranet 是组织内网。内网也需要访问控制，名字带 intra- 不等于天然安全。',('The new leave policy is available on the company intranet.','新的休假政策可以在公司内网上查看。'),('Employees can search the intranet for training materials.','员工可以在内网上搜索培训资料。'),sources=['https://dictionary.cambridge.org/dictionary/english/intranet','https://en.wiktionary.org/wiki/intranet']),
E('intrinsic','/ɪnˈtrɪnzɪk/','内在的；本身具有的','把奖金、掌声和外在包装都拿走，这件事本身仍然有的那种性质。','来自法语 intrinsèque，追溯到拉丁 intrinsecus 在内部，由 intra 内部与 secus 沿着组成；英语结尾后来向 -ic 形式靠拢。不能把中间的 ins 当成独立词根硬拆。',B+[['拉丁 intrinsecus → 法语 intrinsèque','在内部的、内里的'],['英语 intrinsic','由内部位置引申为本质上自带的']],'intrinsic value 是事物本身的价值；intrinsic motivation 是因为活动本身有趣或有意义而想做。说 a feature is intrinsic to something，意思是这个特点属于它自身的重要性质。','intrinsic value；intrinsic interest；intrinsic to the process。','intrinsic 与 extrinsic 相对：前者来自事物自身，后者由外部因素带来。intrinsic 不自动等于好，一种内在缺陷也可以是 intrinsic。',('She studies music for its intrinsic value, not just for exam results.','她学习音乐是看重音乐本身的价值，不只是为了考试成绩。'),('Uncertainty is intrinsic to this kind of research.','不确定性是这类研究本身就有的特点。'),sources=['https://www.etymonline.com/word/intrinsic','https://www.oxfordlearnersdictionaries.com/definition/english/intrinsic']),
E('intrinsically','/ɪnˈtrɪnzɪkli/','本质上；就本身而言','先把外部条件放一边，只看它自己是什么样。','现代对应 intrinsic + -ally；词族中也有较早的 intrinsical 形式。拼写有 -ally，通常读起来并不会多出一个完整重读音节。',B+[['intrinsic／intrinsical','属于本身性质的'],['英语 intrinsically','从事物本身的性质来说']],'intrinsically interesting 是事情本身就有趣，不靠奖励把人吸引过来。nothing intrinsically wrong 表示本身没有错，但在某个具体场合仍可能不合适。这个副词是在限定判断角度。','intrinsically valuable；intrinsically linked；intrinsically motivated。','intrinsically 不是“永远、绝对”。说一个工具本身不坏，不等于它的每种使用方法都没有问题。',('She finds solving puzzles intrinsically rewarding.','她觉得解谜这件事本身就很有满足感。'),('The material is not intrinsically dangerous, but it must be used correctly.','这种材料本身并不危险，但必须正确使用。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/intrinsically','https://www.etymonline.com/word/intrinsic']),
E('intramural','英 /ˌɪntrəˈmjʊərəl/；美 /ˌɪntrəˈmjʊrəl/','校内的；机构内部的','比赛双方都是同一所学校的人，活动发生在这所学校自己的圈子里。','intra- 内部 + 拉丁 murus 墙所构成的 mural 成分。字面是在墙内，英语后来广泛用于校内活动，不必真有一圈围墙。',B+[['拉丁 murus 墙，与 intra- 内部结合','在同一围墙或范围之内'],['英语 intramural','同一学校或机构内部的']],'最常见于美式校园语境，如 intramural sports 校内体育活动。队伍通常由校内成员组成，强调参与和内部竞赛。与别的学校比赛，通常不会用这个词来概括。','intramural sports；an intramural league；intramural basketball。','intercollegiate 是大学与大学之间；intramural 是同一机构内部。intra- 和 inter- 只差一点拼写，边界却完全不同。',('I joined an intramural basketball team in my first year at college.','我大一时加入了一支校内篮球队。'),('The university offers intramural sports for students of all abilities.','这所大学为不同运动水平的学生提供校内体育活动。'),sources=['https://www.etymonline.com/word/intramural','https://www.oxfordlearnersdictionaries.com/us/definition/english/intramural']),
E('intraday','/ˌɪntrəˈdeɪ/','日内的；同一天之内的','把一整天放大看：早上、中午、下午各个时点之间发生的变化。','intra- 在某个范围内 + day 一天；把空间上的“里面”用到时间范围上。',B+[['intra- + day','一天内部'],['英语 intraday','在同一天内发生或观察到的']],'常见于交易、支付与数据报道。intraday high 是当天过程中达到的高点，并不保证收盘还在那个位置；intraday data 可以显示一天内的变化。词本身只说明时间范围。','intraday movements；an intraday high；intraday data。','daily 可以是每天一次或按天汇总；intraday 是把同一天里面的过程展开看。一天一个收盘数字是 daily 数据，可能看不出 intraday 波动。',('The chart shows intraday changes rather than just the closing value.','这张图显示一天内的变化，而不只是收盘值。'),('The payment team reviews intraday cash balances.','支付团队会查看日内各时点的现金余额。'),sources=['https://en.wiktionary.org/wiki/intraday']),
E('intravenous','/ˌɪntrəˈviːnəs/','静脉内的；通过静脉的','把路径指清楚：液体或药物是进入静脉，而不是靠吞咽进入身体。','intra- 在里面 + venous 静脉的；venous 追溯到拉丁 vena 静脉。属于现代医学组合词。',B+[['intra- + venous','在静脉内或进入静脉的'],['英语 intravenous','静脉内的，常缩写 IV']],'常见于 intravenous fluids 静脉输液、intravenous injection 静脉注射。这个词说明部位或给药途径，不能单凭它知道使用了什么药，也不表示所有注射都是静脉注射。','intravenous fluids；intravenous treatment；an intravenous line。','intramuscular 是肌肉内，intravenous 是静脉内。两者都是注射相关词，却指向不同组织。',('The nurse checked the intravenous line.','护士检查了静脉输液管路。'),('The chart records the start time of the intravenous infusion.','记录表上写着静脉输注的开始时间。'),sources=['https://www.cancer.org/cancer/understanding-cancer/glossary.html','https://en.wiktionary.org/wiki/intravenous']),
E('intravenously','/ˌɪntrəˈviːnəsli/','经静脉地；通过静脉','一句话里它回答的是“从哪条途径进入身体”。','intravenous + 副词后缀 -ly，表示采取静脉途径。',B+[['intravenous','静脉内的'],['intravenous + -ly → intravenously','通过静脉给入']],'常跟 give、administer、deliver 等动词。The medicine was given intravenously 的重点是给药方式，不是药的名称或剂量。读到副词时，可以自然转成中文“经静脉给予”。','given intravenously；administered intravenously；delivered intravenously。','intravenous 放在名词前，如 intravenous medication；intravenously 修饰给予的动作。两者意思相关，句子位置不同。',('The medicine was administered intravenously in the hospital.','这份药是在医院经静脉给予的。'),('The report states that the fluids were given intravenously.','报告注明，液体是经静脉输入的。'),sources=['https://www.cdc.gov/std/treatment-guidelines/terms.htm','https://en.wiktionary.org/wiki/intravenously']),
E('intramuscular','英 /ˌɪntrəˈmʌskjələ/；美 /ˌɪntrəˈmʌskjələr/','肌肉内的；肌内注射的','把身体分层看，这个词把位置放在肌肉组织里面。','intra- 内部 + muscular 肌肉的；muscular 来自 muscle 所属的拉丁 musculus 词族。',B+[['intra- + muscular','肌肉组织之内'],['英语 intramuscular','肌内的，常缩写 IM']],'常用组合是 intramuscular injection 肌内注射。它描述到达的组织层次，不是说针必须扎在任何看得见肌肉的位置；在学习词义时，把它与静脉内、皮下等位置区分即可。','an intramuscular injection；the intramuscular route；intramuscular administration。','muscular 也能形容人肌肉发达，intramuscular 却是明确的位置词，不表示“肌肉特别强壮”。',('The leaflet describes the medicine as suitable for intramuscular injection.','说明书将这种药物列为可用于肌内注射。'),('The record distinguishes intramuscular injections from intravenous infusions.','记录中区分了肌内注射和静脉输注。'),sources=['https://www.etymonline.com/word/intramuscular','https://www.cancer.org/cancer/understanding-cancer/glossary.html']),
E('intracellular','英 /ˌɪntrəˈseljələ/；美 /ˌɪntrəˈseljələr/','细胞内的','把一个细胞想成有边界的小房间，这个词说的是房间里面发生的事。','intra- 内部 + cellular 细胞的，属于现代生物学组合词。',B+[['intra- + cellular','一个细胞内部'],['英语 intracellular','位于或发生在细胞内的']],'intracellular processes 是细胞内部的过程，intracellular fluid 是细胞内液。这个词常帮助你在复杂描述中找位置：先不管过程细节，至少知道它发生在细胞边界内。','intracellular transport；intracellular signals；intracellular fluid。','intercellular 是细胞与细胞之间，extracellular 是细胞外。intra-、inter-、extra- 分别回答里面、之间、外面。',('The diagram shows intracellular transport in a plant cell.','图中展示了植物细胞内部的运输过程。'),('Researchers measured changes in intracellular calcium.','研究人员测量了细胞内钙的变化。'),sources=['https://www.cancer.gov/publications/dictionaries/cancer-terms/def/intracellular','https://www.etymonline.com/word/intra-']),
E('intracranial','/ˌɪntrəˈkreɪniəl/','颅内的','把头骨想成外壳，这个词指外壳里面的空间，而不只指脑组织本身。','intra- 内部 + cranial 头颅的；cranial 所属词族来自希腊 kranion 颅骨。',B+[['intra- + cranial','颅骨围成的空间内'],['英语 intracranial','颅内的']],'常见于 intracranial pressure 颅内压、intracranial bleeding 颅内出血。它确定的是位置范围；颅内除了脑，也有血管、液体等，因此颅内与脑内不能处处互换。','intracranial pressure；intracranial structures；an intracranial scan finding。','intracerebral 更具体地指脑内；intracranial 的边界是颅骨，范围较广。中文都与“脑”有关时，仍要看原词。',('The study measured changes in intracranial pressure.','这项研究测量了颅内压的变化。'),('The doctor explained that intracranial means inside the skull.','医生解释说，intracranial 的意思是颅骨里面的。'),sources=['https://en.wiktionary.org/wiki/intracranial']),
E('intrauterine','/ˌɪntrəˈjuːtərɪn/，亦读 /ˌɪntrəˈjuːtəraɪn/','子宫内的；宫内的','用一个位置词，把范围限定到子宫里面。','intra- 内部 + uterine 子宫的；uterine 来自拉丁 uterus 子宫词族。',B+[['intra- + uterine','子宫里面'],['英语 intrauterine','宫内的']],'最常见搭配之一是 intrauterine device，缩写 IUD，中文叫宫内节育器。也能描述位置或发育环境；这个形容词本身不表示某一种特定疾病或某一种固定装置。','an intrauterine device；intrauterine development；intrauterine location。','uterine 是与子宫有关，intrauterine 进一步限定在子宫内部。多出来的 intra- 负责交代位置。',('The abbreviation IUD stands for intrauterine device.','IUD 是 intrauterine device 的缩写，指宫内节育器。'),('The textbook discusses the intrauterine environment.','这本教材讨论了子宫内的环境。'),sources=['https://www.cancer.gov/publications/dictionaries/cancer-terms/def/intrauterine','https://www.cdc.gov/std/treatment-guidelines/terms.htm']),
E('intraocular','英 /ˌɪntrəˈɒkjələ/；美 /ˌɪntrəˈɑːkjələr/','眼内的；眼球内部的','不要只看眼皮和眼睛表面，把范围进一步放到眼球里面。','intra- 内部 + ocular 眼睛的；ocular 来自拉丁 oculus 眼睛。',B+[['intra- + ocular','眼睛里面'],['英语 intraocular','位于眼内或涉及眼内的']],'常见组合是 intraocular pressure 眼压和 intraocular lens 人工晶状体。名字先告诉你位置，再由后面的名词说明是什么；并不是凡是与眼睛有关都叫 intraocular。','intraocular pressure；an intraocular lens；intraocular structures。','ocular 是眼部的，intraocular 是眼内的。眼部表面的问题不因为涉及眼睛就一定属于 intraocular。',('The examination included a measurement of intraocular pressure.','这次检查包括测量眼压。'),('The diagram shows the position of an intraocular lens.','示意图显示了人工晶状体在眼内的位置。'),sources=['https://en.wiktionary.org/wiki/intraocular']),
E('intramolecular','英 /ˌɪntrəməˈlekjələ/；美 /ˌɪntrəməˈlekjələr/','分子内的','不是两个分子互相拉住，而是同一个分子内部的部分发生联系。','intra- 内部 + molecular 分子的，是现代化学组合词。',B+[['intra- + molecular','一个分子内部'],['英语 intramolecular','发生在同一分子之内的']],'intramolecular bonding 指同一分子内部的成键；intramolecular reaction 表示反应涉及同一分子内的部位。先圈出“一个分子”的边界，词义就很直观。','intramolecular forces；intramolecular bonding；an intramolecular reaction。','intermolecular 是分子之间，intramolecular 是分子内部。不要用“很微小所以都一样”来模糊这个关键区别。',('The lesson compares intramolecular bonds with intermolecular attractions.','这节课比较了分子内的化学键和分子间的吸引作用。'),('An intramolecular reaction takes place between parts of the same molecule.','分子内反应发生在同一个分子的不同部位之间。'),sources=['https://en.wiktionary.org/wiki/intramolecular'])
]
ROOT=dict(id='C0610',meaning='在内部；在某个范围之内',core='INTRA = WITHIN',image='先画一条边界：一个细胞、一所学校、一个公司或一天。intra- 把事情放在这条边界里面。',intro='来自拉丁 intra，既能表示空间上的内部，也能表示某段时间之内。这里实际是前缀，仍放在同一学习目录中。与 inter- 之间、extra- 外面配对学，比孤立背中文更好记。',forms='intra- 在现代组合词中通常保留原形，如 intranet、intraday、intracellular。intrinsic 经拉丁和法语传入，拼写变化更多，不能按照现代 intra- 加完整英语单词来硬拆。',branches=[['组织与时间内部','intranet、intramural、intraday、intrastate、intracoastal'],['本身就有','intrinsic、intrinsically'],['身体内的位置','intravenous、intravenously、intramuscular、intracranial、intrauterine、intraocular'],['细胞与分子内部','intracellular、intramolecular']],contrasts='intramural 校内活动，intercollegiate 校际活动；intracellular 细胞内，intercellular 细胞间。先找边界，再判断是在里面还是在两个边界之间。',practice='The students found the intramural sports schedule on the university intranet.\n\n学生们在大学内网上找到了校内体育活动的安排。',words=[x['word'] for x in W]+['intracoastal','intrastate'],exclude={w:'更专门的医学位置词，先保留常见代表' for w in ['intraoperative','intravascular']})
if __name__=='__main__':
 for name,data in [('roots_intra',[ROOT]),('words_intra',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
